import std.io

type Opt2<T> = Some2(T) | None2

pub type AppError = Failed(String)

pub fn main() effect io -> Result<(), AppError> {
    let a: Opt2<Int64> = Some2(2)
    match a {
        Some2(v) => { io.println("${v}") }
        None2 => { io.println("none") }
    }
    return Ok(())
}
